// Bounded research probe, not a production solver. Input is generated by
// boulez_subset_probe.py. Complete-permutation, first-order, three-anchor model.
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <random>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <vector>

struct UInt {
    std::array<uint64_t, 4> x{};
    explicit UInt(uint64_t a = 0) { x[0] = a; }
    bool zero() const { return !(x[0] | x[1] | x[2] | x[3]); }
    void addmul(const UInt& b, uint32_t w) {
        __uint128_t carry = 0;
        for (int i = 0; i < 4; ++i) {
            carry += __uint128_t(b.x[i]) * w + x[i];
            x[i] = uint64_t(carry); carry >>= 64;
        }
        if (carry) throw std::overflow_error("256-bit mass overflow");
    }
    bool operator<(const UInt& b) const {
        for (int i = 3; i >= 0; --i)
            if (x[i] != b.x[i]) return x[i] < b.x[i];
        return false;
    }
    void subtract(const UInt& b) {
        uint64_t borrow = 0;
        for (int i = 0; i < 4; ++i) {
            __uint128_t rhs = __uint128_t(b.x[i]) + borrow;
            uint64_t next = __uint128_t(x[i]) < rhs;
            x[i] -= uint64_t(rhs); borrow = next;
        }
        if (borrow) throw std::logic_error("negative mass");
    }
    std::string decimal() const {
        UInt a = *this;
        if (a.zero()) return "0";
        std::string s;
        while (!a.zero()) {
            __uint128_t remainder = 0;
            for (int i = 3; i >= 0; --i) {
                __uint128_t v = (remainder << 64) | a.x[i];
                a.x[i] = uint64_t(v / 10); remainder = v % 10;
            }
            s.push_back(char('0' + remainder));
        }
        std::reverse(s.begin(), s.end()); return s;
    }
};

UInt below(const UInt& limit, std::mt19937_64& rng) {
    int top = 3;
    while (top && !limit.x[top]) --top;
    int bits = 64 - __builtin_clzll(limit.x[top]);
    uint64_t mask = bits == 64 ? ~uint64_t(0) : (uint64_t(1) << bits) - 1;
    for (;;) {
        UInt r;
        for (int i = 0; i <= top; ++i) r.x[i] = rng();
        r.x[top] &= mask;
        if (r < limit) return r;
    }
}

using Clock = std::chrono::steady_clock;
double seconds(Clock::time_point t) {
    return std::chrono::duration<double>(Clock::now() - t).count();
}
int pop(uint32_t a) { return __builtin_popcount(a); }

int main() {
    try {
        int f, before, sample_count, mode;
        uint64_t budget;
        std::cin >> f >> before >> sample_count >> mode >> budget;
        if (f < 1 || f > 21 || before < 0 || before > f)
            throw std::runtime_error("invalid probe dimensions");
        const int n = f + 3, start = f, anchor = f + 1, end = f + 2;
        std::vector<std::vector<uint32_t>> w(n, std::vector<uint32_t>(n));
        std::vector<uint32_t> out(n), incoming(n);
        for (int a = 0; a < n; ++a) for (int b = 0; b < n; ++b) {
            std::cin >> w[a][b];
            if (mode == 1) w[a][b] = bool(w[a][b]);
            if (a == b) w[a][b] = 0;
            if (w[a][b]) { out[a] |= 1u << b; incoming[b] |= 1u << a; }
        }
        if (!std::cin) throw std::runtime_error("incomplete input");
        const uint32_t size = 1u << f, all = size - 1;
        const uint64_t cells = uint64_t(f) * (size / 2);
        const uint64_t bytes = uint64_t(size) * 8 + cells * sizeof(UInt);
        if (bytes + 1024 * 1024 > budget) throw std::runtime_error("allocation budget");
        auto begin = Clock::now();
        std::vector<uint32_t> forward(size), backward(size);
        std::vector<uint64_t> reached(n + 1), live(n + 1), arcs(n + 1);
        std::vector<uint64_t> boolean_nodes(n + 1), weighted_nodes(n + 1);
        forward[0] = 1u << start;
        // Both sides of the middle anchor share a mask but have distinct last bits.
        for (uint32_t s = 0; s < size; ++s) {
            int k = pop(s);
            uint32_t last = forward[s];
            if (k == before) {
                if (last & incoming[anchor]) forward[s] |= 1u << anchor;
                last = forward[s] & (1u << anchor);
            }
            uint32_t destinations = 0;
            while (last) {
                int a = __builtin_ctz(last); last &= last - 1;
                destinations |= out[a];
            }
            destinations &= all ^ s;
            while (destinations) {
                uint32_t bit = destinations & -destinations; destinations -= bit;
                forward[s | bit] |= bit;
            }
        }
        // Backward feasibility independent of forward reachability.
        for (int64_t si = size - 1; si >= 0; --si) {
            uint32_t s = uint32_t(si), productive = 0, left = all ^ s;
            int k = pop(s);
            while (left) {
                uint32_t bit = left & -left; left -= bit;
                if (backward[s | bit] & bit) productive |= incoming[__builtin_ctz(bit)];
            }
            if (k == f) productive = incoming[end];
            if (k == before) {
                if (productive & (1u << anchor))
                    backward[s] = (1u << anchor) | (incoming[anchor] & s);
                // Supports the small-oracle special case with the anchor second.
                if (k == 0 && (backward[s] & (1u << anchor)) && w[start][anchor])
                    backward[s] |= 1u << start;
            } else backward[s] = productive & (s | (s == 0 ? 1u << start : 0));
        }
        double reach_seconds = seconds(begin);
        auto reduction_start = Clock::now();
        for (uint32_t s = 0; mode != 2 && s < size; ++s) {
            int k = pop(s), depth = 1 + k + (k > before);
            uint32_t last = forward[s] & ~(1u << anchor);
            reached[depth] += pop(last);
            last &= backward[s]; live[depth] += pop(last);
            uint32_t productive = 0, left = all ^ s;
            while (left) {
                uint32_t bit = left & -left; left -= bit;
                if (backward[s | bit] & bit) productive |= bit;
            }
            if (k == f) productive = 1u << end;
            if (k == before) {
                reached[depth + 1] += bool(forward[s] & (1u << anchor));
                if ((forward[s] & backward[s]) & (1u << anchor)) {
                    ++live[depth + 1]; ++boolean_nodes[depth + 1];
                    ++weighted_nodes[depth + 1];
                    arcs[depth + 1] += pop(productive & out[anchor]);
                }
                productive = backward[s] & (1u << anchor);
            }
            // Different masks cannot merge: each accepting suffix uses exactly
            // the complementary alphabet. Within a mask, these signatures give
            // exact Boolean equivalence / weighted equivalence up to a scalar.
            std::vector<uint32_t> supports;
            std::vector<std::array<uint32_t, 24>> weights;
            while (last) {
                int a = __builtin_ctz(last); last &= last - 1;
                uint32_t support = productive & out[a];
                arcs[depth] += pop(support);
                if (std::find(supports.begin(), supports.end(), support) == supports.end())
                    supports.push_back(support);
                std::array<uint32_t, 24> signature{};
                uint32_t bits = support, divisor = 0;
                while (bits) {
                    int b = __builtin_ctz(bits); bits &= bits - 1;
                    signature[b] = w[a][b]; divisor = std::gcd(divisor, w[a][b]);
                }
                if (!divisor) throw std::logic_error("live state without successor");
                for (auto& v : signature) v /= divisor;
                if (std::find(weights.begin(), weights.end(), signature) == weights.end())
                    weights.push_back(signature);
            }
            boolean_nodes[depth] += supports.size(); weighted_nodes[depth] += weights.size();
        }
        double reduction_seconds = seconds(reduction_start);
        auto count_start = Clock::now();
        std::vector<UInt> mass(cells);
        auto index = [&](uint32_t s, int a) -> uint64_t {
            uint32_t low = (1u << a) - 1;
            return uint64_t(a) * (size / 2) + (s & low) + ((s >> (a + 1)) << a);
        };
        // Weighted suffix mass immediately after the middle anchor. Recomputed
        // on sampling queries to avoid another dense 64 MiB array.
        auto anchor_mass = [&](uint32_t s) {
            UInt value;
            if (s == all) { value = UInt(w[anchor][end]); return value; }
            uint32_t choices = out[anchor] & (all ^ s);
            while (choices) {
                uint32_t bit = choices & -choices; choices -= bit;
                int b = __builtin_ctz(bit);
                value.addmul(mass[index(s | bit, b)], w[anchor][b]);
            }
            return value;
        };
        UInt total;
        uint32_t maximum_bits = 0;
        for (int64_t si = size - 1; si >= 0; --si) {
            uint32_t s = uint32_t(si), last = forward[s] & backward[s] & all;
            int k = pop(s);
            UInt at_anchor;
            if (k == before) at_anchor = anchor_mass(s);
            while (last) {
                int a = __builtin_ctz(last); last &= last - 1;
                UInt value;
                if (k == before) value.addmul(at_anchor, w[a][anchor]);
                else if (k == f) value = UInt(w[a][end]);
                else {
                    uint32_t choices = out[a] & (all ^ s);
                    while (choices) {
                        uint32_t bit = choices & -choices; choices -= bit;
                        int b = __builtin_ctz(bit);
                        value.addmul(mass[index(s | bit, b)], w[a][b]);
                    }
                }
                if (value.zero()) throw std::logic_error("live state has zero mass");
                for (int j = 3; j >= 0; --j) if (value.x[j]) {
                    maximum_bits = std::max(maximum_bits, uint32_t(j * 64 + 64 - __builtin_clzll(value.x[j])));
                    break;
                }
                mass[index(s, a)] = value;
            }
        }
        if (before == 0) total.addmul(anchor_mass(0), w[start][anchor]);
        else for (int b = 0; b < f; ++b)
            total.addmul(mass[index(1u << b, b)], w[start][b]);
        double count_seconds = seconds(count_start);
        auto sample_start = Clock::now();
        std::mt19937_64 rng(1729);
        std::vector<std::vector<int>> samples;
        std::vector<uint64_t> first_counts(n);
        for (int iteration = 0; iteration < sample_count && !total.zero(); ++iteration) {
            uint32_t s = 0; int a = start;
            std::vector<int> path{start};
            while (int(path.size()) < n) {
                std::vector<std::pair<int, UInt>> branches;
                UInt sum;
                if (int(path.size()) == before + 1) {
                    UInt value; value.addmul(anchor_mass(s), w[a][anchor]);
                    branches.push_back({anchor, value}); sum = value;
                } else if (s == all) {
                    branches.push_back({end, UInt(w[a][end])}); sum = UInt(w[a][end]);
                } else {
                    uint32_t choices = out[a] & (all ^ s);
                    while (choices) {
                        uint32_t bit = choices & -choices; choices -= bit;
                        int b = __builtin_ctz(bit); UInt value;
                        value.addmul(mass[index(s | bit, b)], w[a][b]);
                        if (!value.zero()) { branches.push_back({b, value}); sum.addmul(value, 1); }
                    }
                }
                if (sum.zero()) throw std::logic_error("sample reached dead state");
                UInt ticket = below(sum, rng);
                for (const auto& branch : branches) {
                    if (ticket < branch.second) { a = branch.first; break; }
                    ticket.subtract(branch.second);
                }
                path.push_back(a); if (a < f) s |= 1u << a;
            }
            ++first_counts[path[1]];
            auto sorted = path; std::sort(sorted.begin(), sorted.end());
            for (int j = 0; j < n; ++j)
                if (sorted[j] != j) throw std::logic_error("sample is not a permutation");
            if (path[0] != start || path[before + 1] != anchor || path.back() != end)
                throw std::logic_error("sample violates anchor");
            for (int j = 1; j < n; ++j)
                if (!w[path[j - 1]][path[j]]) throw std::logic_error("sample zero edge");
            samples.push_back(path);
        }
        double sample_seconds = seconds(sample_start);
        struct rusage usage{}; getrusage(RUSAGE_SELF, &usage);
        uint64_t rss = usage.ru_maxrss;
#ifndef __APPLE__
        rss *= 1024;
#endif
        std::cout << "{\"status\":\"complete\",\"mass\":\"" << total.decimal()
                  << "\",\"mdd_analysis_performed\":" << (mode == 2 ? "false" : "true")
                  << ",\"allocated_array_bytes\":" << bytes << ",\"peak_rss_bytes\":" << rss
                  << ",\"reach_seconds\":" << reach_seconds
                  << ",\"reduction_seconds\":" << reduction_seconds
                  << ",\"count_seconds\":" << count_seconds
                  << ",\"sample_seconds\":" << sample_seconds
                  << ",\"maximum_suffix_mass_bits\":" << maximum_bits;
        auto array = [&](const char* name, const auto& values) {
            std::cout << ",\"" << name << "\":[";
            bool comma = false;
            for (auto v : values) { if (comma) std::cout << ','; std::cout << v; comma = true; }
            std::cout << ']';
        };
        array("reachable_by_depth", reached); array("live_by_depth", live);
        array("arcs_by_depth", arcs); array("boolean_mdd_by_depth", boolean_nodes);
        array("weighted_mdd_by_depth", weighted_nodes); array("sample_first_counts", first_counts);
        std::cout << ",\"first_branch_masses\":[";
        for (int b = 0; b < n; ++b) {
            if (b) std::cout << ',';
            UInt value;
            if (before == 0 && b == anchor) value = total;
            else if (before > 0 && b < f)
                value.addmul(mass[index(1u << b, b)], w[start][b]);
            std::cout << '"' << value.decimal() << '"';
        }
        std::cout << ']';
        std::cout << ",\"samples\":[";
        for (size_t i = 0; i < samples.size(); ++i) {
            if (i) std::cout << ','; std::cout << '[';
            for (size_t j = 0; j < samples[i].size(); ++j) {
                if (j) std::cout << ','; std::cout << samples[i][j];
            }
            std::cout << ']';
        }
        std::cout << "]}\n";
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n'; return 1;
    }
}
